class BookManagement:
    def __init__(self):
        self.inventory = {}

    def add_book(self, title, quantity=1):
        if title in self.inventory:
            self.inventory[title] += quantity
        else:
            self.inventory[title] = quantity

    def remove_book(self, title, quantity):
        if self._is_valid_removal(title, quantity):
            self._decrement_inventory(title, quantity)

    def _is_valid_removal(self, title, quantity):
        return title in self.inventory and self.inventory[title] >= quantity

    def _decrement_inventory(self, title, quantity):
        self.inventory[title] -= quantity
        if self.inventory[title] == 0:
            del self.inventory[title]

    def view_inventory(self):
        return dict(self.inventory)

    def view_book_quantity(self, title):
        return self._get_book_quantity(title)

    def _get_book_quantity(self, title):
        return self.inventory.get(title, 0)
